package weekly_Assignments;

public class CalculateQuantity {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		/*
		 Question 3 — Calculate Product Details
		Create a Java program with the following variables:
    	• Product Price = 499.50
    	• Quantity = 3
		Calculate the total price using the variables and print:
		Product Price: 499.50
		Quantity: 3
		Total Price: 1498.50
		 */
		
		double product_price = 499.50;
		int quantity = 3;
		double total_price = product_price * quantity;
		System.out.println("The total price is: "+total_price);

	}

}
